# -*- coding: utf-8 -*-
# 팟캐스트 탭 새 디자인 B: 칩 줄 없애고 → 제목(TOP 50) + 돋보기 / 1위 먹색 큰 카드 / 2~10위 목록(더 보기 50위)
# / 맨 아래 '주제로 찾기' 2열 타일 + '팟캐스트란? ⓘ'
# (지금 팟캐스트 탭 부분만 통째로 바꿈 — 회차 목록·미니플레이어·재생 화면은 그대로)
import base64, os, sys

PATH = os.path.join('lib', 'podcast', 'podcast_screens.dart')
NEW = base64.b64decode("").decode('utf-8')
START = 'class _PodcastTabState extends State<PodcastTab> {'
END = '// ───────────────────────── 팟캐스트 하나: 회차 목록'


def fail(m):
    print('❌', m, '— 아무것도 저장하지 않았어요.')
    sys.exit(1)


if not os.path.exists(PATH):
    fail('파일이 없어요: ' + PATH)
raw = open(PATH, 'rb').read().decode('utf-8')
crlf = '\r\n' in raw
s = raw.replace('\r\n', '\n')
if 'bool _latestLoading' in s:
    print('이미 적용돼 있어요')
    sys.exit(0)
a = s.find(START)
b = s.find(END, a)
if a < 0 or b < 0:
    fail('팟캐스트 탭 부분을 못 찾았어요')
s = s[:a] + NEW + s[b:]
# 예전 탭에서만 쓰던 import 정리
s = s.replace("import 'package:shared_preferences/shared_preferences.dart';\n", '')
if s.count('(') != s.count(')') or s.count('{') != s.count('}') or s.count('[') != s.count(']'):
    fail('괄호가 안 맞아요')
print('✔ 팟캐스트 탭 → 새 디자인 B')
if crlf:
    s = s.replace('\n', '\r\n')
open(PATH, 'wb').write(s.encode('utf-8'))
print('저장했어요:', PATH)
